const SPARKLE = 'M20.4,3.78c1.83,4.96,2.75,7.44,4.57,9.26,1.81,1.81,4.29,2.73,9.25,4.56l3.78,1.4-3.78,1.4c-4.96,1.83-7.44,2.75-9.26,4.57-1.81,1.81-2.73,4.29-4.56,9.25l-1.4,3.78-1.4-3.78c-1.83-4.96-2.75-7.44-4.57-9.26-1.81-1.81-4.29-2.73-9.25-4.56l-3.78-1.4,3.78-1.4c4.96-1.83,7.44-2.75,9.26-4.57,1.81-1.81,2.73-4.29,4.56-9.25l1.4-3.78,1.4,3.78Z'
const ROUNDED_RECT = 'M43.81,8.74h23.13c10.93,0,19.78,8.86,19.78,19.78v38.13c0,10.93-8.86,19.78-19.78,19.78H28.81c-10.93,0-19.78-8.86-19.78-19.78v-23.13'

function SvgBase({ children, viewBox = '0 0 90 90', className }: { children: React.ReactNode; viewBox?: string; className?: string }) {
  return (
    <svg viewBox={viewBox} className={cn('size-full', className)} fill="none" aria-hidden>
      {children}
    </svg>
  )
}

function StrokePath({ d }: { d: string }) {
  return <path d={d} stroke="currentColor" strokeWidth={6} strokeLinecap="round" strokeLinejoin="round" />
}
function FillPath({ d }: { d: string }) {
  return <path d={d} fill="currentColor" />
}
function FillSparkle() {
  return <FillPath d={SPARKLE} />
}
function OuterRect({ offsetX = 0 }: { offsetX?: number }) {
  // Video 的矩形 x 偏移 -0.32
  const d = offsetX !== 0 ? ROUNDED_RECT.replace('M43.81', `M${43.81 + offsetX}`).replace('M28.81', `M${28.81 + offsetX}`) : ROUNDED_RECT
  return <StrokePath d={d} />
}

